style.css:
@-moz-document domain("ambitious.social") {
/* === Core surfaces === */
  [class*="bg-white"] {
    background-color: #15202b !important;
  }
  [class*="bg-[#F7F9F9]"] {
    background-color: #1e2732 !important;
  }
  html, body {
    background-color: #15202b !important;
  }

  /* === Borders / dividers === */
  [class*="border-[#EFF3F4]"],
  [class*="border-gray-200"],
  [class*="border-[#CFD9DE]"] {
    border-color: #38444d !important;
  }
  [class*="bg-[#CFD9DE]"] {
    background-color: #38444d !important;
  }

  /* === Text colors === */
  [class*="text-[#0F1419]"] {
    color: #e7e9ea !important;
  }
  [class*="text-[#536471]"] {
    color: #8b98a5 !important;
  }
  [class*="text-gray-700"],
  [class*="text-gray-600"] {
    color: #8b98a5 !important;
  }
  [class*="text-gray-900"] {
    color: #e7e9ea !important;
  }
  [class*="text-gray-400"] {
    color: #6e767d !important;
  }
  [class*="placeholder-gray-500"] {
    color: #8b98a5 !important;
  }
  [class*="placeholder-gray-500"]::placeholder {
    color: #8b98a5 !important;
  }

  /* === Dark CTA buttons that were black-on-white (Post, Get app, Say hi, etc.) === */
  [class*="bg-[#0F1419]"] {
    background-color: #1d9bf0 !important;
  }
  [class*="hover:bg-black"]:hover {
    background-color: #1a8cd8 !important;
  }

  /* === Subtle hover states (rgba black overlays that vanish on dark bg) === */
  [class*="hover:bg-[#0F1419]/"]:hover,
  [class*="hover:bg-gray-100"]:hover,
  [class*="hover:bg-gray-50"]:hover {
    background-color: rgba(255, 255, 255, 0.08) !important;
  }

  /* === Search input and other white inputs === */
  input, textarea, select {
    background-color: #1e2732 !important;
    color: #e7e9ea !important;
    border-color: #38444d !important;
  }

  /* === Prediction bar tracks (gray backing bars) === */
  [class*="bg-gray-100"],
  [class*="bg-[#EFF3F4]"] {
    background-color: #38444d !important;
  }

  /* === Prediction Yes/No vote buttons (very light green/red on white → too pale on dark) === */
  [class*="bg-emerald-50"] {
    background-color: rgba(0, 186, 124, 0.15) !important;
  }
  [class*="text-emerald-700"] {
    color: #00ba7c !important;
  }
  [class*="bg-red-50"] {
    background-color: rgba(244, 33, 46, 0.15) !important;
  }
  [class*="text-red-700"] {
    color: #f4212e !important;
  }

  /* === Post image/video wrapper background === */
  [class*="border-[#CFD9DE]"][class*="bg-[#F7F9F9]"] {
    background-color: #1e2732 !important;
  }

  /* === Keep brand accents as-is (already visible on dark): text-primary, #1D9BF0, #00BA7C, #F91880, #4A9EFF === */

  /* === Never touch actual media === */
  img, video, picture {
    filter: none !important;
  }

  /* === Scrollbar === */
  ::-webkit-scrollbar {
    background: #15202b;
  }
  ::-webkit-scrollbar-thumb {
    background: #38444d;
    border-radius: 8px;
  }
}
